const items = $input.all();
const now = Date.now();
let cooldownHours = 48;
try {
  cooldownHours = $('⚙️ Variables de Configuración').first().json.COOLDOWN_HOURS || 48;
} catch(e) {}
const COOLDOWN_MS = cooldownHours * 60 * 60 * 1000;

// Filter out empty rows (like row 23 with empty PRODUCTO)
const validItems = items.filter(item => (item.json?.PRODUCTO || '').toString().trim() !== '');

const driveFiltered = validItems.filter(item => {
  const driveId = (item.json?.DRIVE_ID || '').toString().trim();
  return driveId.length >= 25 && /^[a-zA-Z0-9_-]+$/.test(driveId);
});

const candidatos = driveFiltered.map(item => {
  const p = item.json;

  const fechaEnvio = p.FECHA_ENVIO ? new Date(p.FECHA_ENVIO).getTime() : 0;
  const facebookElegible = (p.FACEBOOK || '') !== 'ENVIADO' || (now - fechaEnvio >= COOLDOWN_MS);
  const instagramElegible = (p.INSTAGRAM || '') !== 'ENVIADO' || (now - fechaEnvio >= COOLDOWN_MS);
  const whatsappElegible = (p.WHATSAPP || '') !== 'ENVIADO' || (now - fechaEnvio >= COOLDOWN_MS);
  const telegramElegible = (p.TELEGRAM || '') !== 'ENVIADO' || (now - fechaEnvio >= COOLDOWN_MS);

  return {
    PRODUCTO: p.PRODUCTO,
    DRIVE_ID: p.DRIVE_ID,
    CATEGORIA: p.CATEGORIA || p.CATEGORÍA,
    STOCK: p.STOCK,
    REBAJA: p.REBAJA,
    facebook_elegible: facebookElegible,
    instagram_elegible: instagramElegible,
    whatsapp_elegible: whatsappElegible,
    telegram_elegible: telegramElegible,
  };
});

return [{
  json: {
    candidatos
  }
}];

let fileContent = "";
const binaryData = $input.first().binary?.data;
if (binaryData) {
  const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  fileContent = binaryBuffer.toString('utf8');
} else {
  const allItems = $input.all();
  fileContent = allItems[0]?.json?.data || allItems[0]?.json?.fileContent;
}

if (typeof fileContent === "string") {
  fileContent = JSON.parse(fileContent);
}

return [{
  json: fileContent
}];

