const candidates = $('⚙️ Evaluar Estado Multicanal').first().json.candidatos || [];
const selectedModel = $('⚙️ Configurar y Registrar Modelo').first().json.selectedModel;
let extraPrompt = "";
try {
  extraPrompt = $('⚙️ Variables de Configuración').first().json.EXTRA_PROMPT || "";
} catch(e) {}

let systemPrompt = "Analiza el catálogo de candidatos. Selecciona un producto para cada canal de publicación (Facebook, Instagram, WhatsApp, Telegram) que tenga su elegibilidad en true. Prioriza los que estén en rebaja y tengan bajo stock de forma agrupada por categorías. REGLA CRITICA: Si para un canal NO existe ningun producto elegible, OMITE completamente esa propiedad en tu respuesta - nunca inventes productos ni uses placeholders como N/A. Si la lista de candidatos esta vacia, responde solo {\"resetNeeded\": false} sin ninguna propiedad de canal.";

if (extraPrompt && extraPrompt.trim().length > 0) {
  systemPrompt += "\n\nInstrucción Adicional Prioritaria del Usuario: " + extraPrompt.trim();
}

const payload = {
  model: selectedModel,
  response_format: {
    type: "json_schema",
    json_schema: {
      name: "marketing_decision",
      schema: {
        type: "object",
        properties: {
          facebook_product: {
            type: "object",
            properties: {
              PRODUCTO: { type: "string" },
              DRIVE_ID: { type: "string" }
            }
          },
