              DRIVE_ID: { type: "string" }
            }
          }
        }
      }
    }
  },
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: candidates.length === 0
        ? 'La lista de candidatos esta VACIA. No hay productos disponibles para publicar en este momento. Responde EXACTAMENTE este JSON y nada mas: {"resetNeeded": false}'
        : "Catálogo de candidatos: " + JSON.stringify(candidates) }
  ]
};
return [{ json: payload }];

const fs = require('fs');
const path = '/data/tmp_post/last_model.json';

// 1. Detect command from Webhook
let cmd = "";
try {
  const webhookCmd = $('Webhook Trigger').first().json.query?.cmd;
  if (webhookCmd) cmd = webhookCmd;
} catch(e) {}

try {
  const webhookMsg = $('Webhook Trigger').first().json.body?.message;
  if (webhookMsg) {
    if (webhookMsg.includes("/pro")) cmd = "/pro";
    if (webhookMsg.includes("/free")) cmd = "/free";
  }
} catch(e) {}

// 2. Load last model
let lastModel = "gemini/gemini-3.5-flash";
try {
  if (fs.existsSync(path)) {
    const raw = fs.readFileSync(path, 'utf8');
    const data = JSON.parse(raw);
    if (data && data.model) {
      lastModel = data.model;
    }
  }
} catch(e) {}

// 3. Determine active model
let selectedModel = lastModel;
if (cmd.includes("/pro")) {
  selectedModel = "gemini/gemini-3.5-flash";
} else if (cmd.includes("/free")) {
  selectedModel = "gemini/gemini-3.5-flash";
}

// 4. Save selected model
try {
  fs.writeFileSync(path, JSON.stringify({ model: selectedModel }), 'utf8');
} catch(e) {}

return [{
  json: {
    selectedModel,
    cmdDetected: cmd || "none"
  }
}];

